import React, { Component } from 'react'
import LayoutContentStyle from '../../../../../components/utility/layoutContent'
import { PolicyEndorsementStyle } from './index.style'
import agentAction from '../../../../redux/agent/actions'
import insuranceAction from '../../../../../redux/policy/actions'
import { errorHandler } from '../../../PolicyList/components/PolicyEditForm/forItems'
import { connect } from 'react-redux'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../constants'
import CircularLoader from '../../../../../components/CircularLoader'
import { Icon, Button, Form, Input, message, Upload, notification } from 'antd'
import moment from 'moment-timezone'

const { getAgentInsuranceCoreData } = agentAction
const { getEditPolicyAttribute, uploadPolicyFile, resetReduxState, editPolicyDetails } = insuranceAction
const { TextArea } = Input

class PolicyCoreEndorsement extends Component {
  constructor (props) {
    super(props)
    this.state = {
      showPreview: false,
      policyCoreDetail: {},
      policyAttributeData: {
        policy_number: {
          type: 'string',
          field_type: 'string',
          parent_code: ''
        },
        policy_certificate: {
          type: 'multiple_hybrid_files',
          field_type: 'multiple_image',
          parent_code: ''
        }
      },
      premiumNoteDocument: [],
      commissionNoteDocument: [],
      extraDocument: [],
      uploadingStatus: false,
      uploadType: ''
    }
    this.policyId = this.props.match.params.policy_id
  }

  componentDidUpdate (prevProps) {
    const { agentCorePolicy, uploadPolicyFileStatus } = this.props
    const { uploadType } = this.state
    if (agentCorePolicy !== prevProps.agentCorePolicy) {
      this.setState({ policyCoreDetail: agentCorePolicy })
    }
    if (uploadPolicyFileStatus === 'success') {
      if (uploadType === 'premium note') {
        this.setState(prevState => ({
          premiumNoteDocument: [...prevState.premiumNoteDocument, this.props.uploadPolicyFileData.url],
          uploadingStatus: false
        }))
      }
      if (uploadType === 'commission note') {
        this.setState(prevState => ({
          commissionNoteDocument: [...prevState.commissionNoteDocument, this.props.uploadPolicyFileData.url],
          uploadingStatus: false
        }))
      }
      if (uploadType === 'extra note') {
        this.setState(prevState => ({
          extraDocument: [...prevState.extraDocument, this.props.uploadPolicyFileData.url],
          uploadingStatus: false
        }))
      }
      this.props.resetReduxState([
        'uploadPolicyFileStatus',
        'uploadPolicyFileData'
      ])
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { editPolicyDataMessage } = nextProps

    if (editPolicyDataMessage === 'success') {
      notification.success({
        message: 'Policy Edited Successfully',
        description: ''
      })
      // Reset redux state
      this.props.resetReduxState(['editPolicyDataMessage'])
      this.props.resetReduxState(['uploadPolicyFileStatus', 'uploadPolicyFileData'])

      // Redirect after successful submission
      this.props.history.push(`/agent/policy/corepolicy/${this.policyId}`)
    }
    if (editPolicyDataMessage && editPolicyDataMessage !== 'success') {
      errorHandler.call(this, {
        submitError: nextProps.submitEditPolicyData,
        detailMessage: nextProps.editPolicyData.error,
        resetFunction: () => this.props.resetReduxState(['editPolicyDataMessage'])
      })
    }
  }

  componentDidMount () {
    this.props.getAgentInsuranceCoreData({ policyId: this.policyId })
  }

  handleBackPolicyClick = () => {
    const { history } = this.props
    history.goBack()
  };

  beforeUpload = (file) => {
    // file size validation for 10MB
    const isLt10M = file.size / 1024 / 1024 <= 10
    if (!isLt10M) {
      message.error('file must be smaller than 10MB!')
    }
    return isLt10M
  };

  handleRemovePremiumNoteItem = (urlToRemove) => {
    this.setState(prevState => ({
      premiumNoteDocument: prevState.premiumNoteDocument.filter(url => url !== urlToRemove)
    }))
  };

  handleRemoveCommissionNoteItem = (urlToRemove) => {
    this.setState(prevState => ({
      commissionNoteDocument: prevState.commissionNoteDocument.filter(url => url !== urlToRemove)
    }))
  };

  handleRemoveExtraNoteItem = (urlToRemove) => {
    this.setState(prevState => ({
      extraDocument: prevState.extraDocument.filter(url => url !== urlToRemove)
    }))
  };

  customRequest = ({ file, uploadType }) => {
    const formData = new FormData()
    if (file.name) {
      const fileName = file.name.split('.')[0]
      formData.append('file', file)
      formData.append(
        'path',
        `${PATH_FOR_AGENT_FILE_UPLOAD}/${fileName}_${Date.parse(new Date())}`
      )
      formData.append('identifier', 'agent')
      this.props.uploadPolicyFile({ body: formData })
      this.setState({
        uploadingStatus: true,
        uploadType
      })
    }
  };

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { dataProfile, agentCorePolicy } = this.props
        const { extraDocument, premiumNoteDocument, commissionNoteDocument } = this.state
        const payload = {
          request: {
            extra_document_urls: extraDocument,
            premium_note_urls: premiumNoteDocument,
            commission_note_urls: commissionNoteDocument
          },
          audit_id: `PP-${Math.floor(1000 + Math.random() * 9000)}${this.policyId}`,
          updated_by_user: dataProfile?.email ?? '',
          coverage_end: moment(agentCorePolicy.Payments[0].CoverageEndDate).format('YYYY-MM-DD HH:mm:ss'),
          coverage_start: moment(agentCorePolicy.Payments[0].CoverageStartDate).format('YYYY-MM-DD HH:mm:ss'),
          premium: Number(agentCorePolicy.Premium),
          remarks: values.remarks,
          enqueue_flag: agentCorePolicy.enqueue_flag
          // endosement:{}
        }
        const payloadData = {
          internalId: this.policyId,
          body: payload
        }
        this.props.editPolicyDetails(payloadData)
      }
    })
  }

  render () {
    const { agentCorePolicy, getCorePolicyDetailLoader } = this.props
    const { getFieldDecorator } = this.props.form
    const policyDetailRequest = agentCorePolicy?.Request ?? {}
    return (
      <CircularLoader isSpining={getCorePolicyDetailLoader}>
        <PolicyEndorsementStyle>
          <LayoutContentStyle>
            <Button className='btn-back' onClick={this.handleBackPolicyClick}>
              <Icon type='left' /> back
            </Button>
            <Form onSubmit={this.handleSubmit}>
              <Form.Item label='Policy Number'>
                {getFieldDecorator('policy_number', {
                  rules: [{ required: true, message: 'Policy number cannot be blank' }],
                  initialValue: policyDetailRequest.policy_number
                })(<Input />)}
              </Form.Item>
              <Form.Item label='Premium Note'>
                {getFieldDecorator('premium_note_urls', {
                  rules: [{ required: false }]
                })(
                  <>
                    <div style={{ display: 'flex', width: '100%', flexWrap: 'wrap', gap: '15px', marginBottom: '15px' }}>
                      {this.state.premiumNoteDocument.map((item, index) => {
                        const isImage = /\.(jpg|jpeg|png)$/.test(item)
                        return (
                          <div style={{ display: 'flex', width: '150px', marginRight: '10px' }} key={index}>
                            {isImage
                              ? (
                                <img
                                  src={item}
                                  alt={`Preview ${index}`}
                                  width={150}
                                  height={150}
                                  style={{ objectFit: 'cover' }}
                                />
                                )
                              : (
                                <object
                                  type='application/pdf'
                                  data={item}
                                  width={150}
                                  height={150}
                                  aria-label={`Policy Doc Pdf ${index}`}
                                />
                                )}

                            {/* Close button to remove the item */}
                            <div
                              style={{
                                display: 'flex',
                                alignItems: 'start',
                                justifyContent: 'start',
                                cursor: 'pointer',
                                marginLeft: '8px'
                              }}
                              onClick={() => this.handleRemovePremiumNoteItem(item)}
                            >
                              <Icon type='close' />
                            </div>
                          </div>
                        )
                      })}
                    </div>

                    <Upload
                      name='upload'
                      showUploadList={false}
                      customRequest={(data) => this.customRequest({ ...data, uploadType: 'premium note' })}
                      listType='picture'
                      accept='.pdf, .jpg, .jpeg, .png'
                      beforeUpload={(file) => this.beforeUpload(file)}
                    >
                      {this.state.uploadingStatus
                        ? (
                          <CircularLoader isSpining />
                          )
                        : (
                          <Button>
                            <Icon type='upload' /> Click to upload
                          </Button>
                          )}
                    </Upload>
                  </>

                )}
              </Form.Item>
              <Form.Item label='Commission Note'>
                {getFieldDecorator('commission_note_urls', {
                  rules: [{ required: false }]
                })(
                  <>
                    <div style={{ display: 'flex', width: '100%', flexWrap: 'wrap', gap: '15px', marginBottom: '15px' }}>
                      {this.state.commissionNoteDocument.map((item, index) => {
                        const isImage = /\.(jpg|jpeg|png)$/.test(item)
                        return (
                          <div style={{ display: 'flex', width: '150px', marginRight: '10px' }} key={index}>
                            {isImage
                              ? (
                                <img
                                  src={item}
                                  alt={`Preview ${index}`}
                                  width={150}
                                  height={150}
                                  style={{ objectFit: 'cover' }}
                                />
                                )
                              : (
                                <object
                                  type='application/pdf'
                                  data={item}
                                  width={150}
                                  height={150}
                                  aria-label={`Policy Doc Pdf ${index}`}
                                />
                                )}

                            {/* Close button to remove the item */}
                            <div
                              style={{
                                display: 'flex',
                                alignItems: 'start',
                                justifyContent: 'start',
                                cursor: 'pointer',
                                marginLeft: '8px'
                              }}
                              onClick={() => this.handleRemoveCommissionNoteItem(item)}
                            >
                              <Icon type='close' />
                            </div>
                          </div>
                        )
                      })}
                    </div>

                    <Upload
                      name='upload'
                      showUploadList={false}
                      customRequest={(data) => this.customRequest({ ...data, uploadType: 'commission note' })}
                      listType='picture'
                      accept='.pdf, .jpg, .jpeg, .png'
                      beforeUpload={(file) => this.beforeUpload(file)}
                    >
                      {this.state.uploadingStatus
                        ? (
                          <CircularLoader isSpining />
                          )
                        : (
                          <Button>
                            <Icon type='upload' /> Click to upload
                          </Button>
                          )}
                    </Upload>
                  </>

                )}
              </Form.Item>
              <Form.Item label='Extra Document'>
                {getFieldDecorator('extra_document_urls', {
                  rules: [{ required: false }]
                })(
                  <>
                    <div style={{ display: 'flex', width: '100%', flexWrap: 'wrap', gap: '15px', marginBottom: '15px' }}>
                      {this.state.extraDocument.map((item, index) => {
                        const isImage = /\.(jpg|jpeg|png)$/.test(item)
                        return (
                          <div style={{ display: 'flex', width: '150px', marginRight: '10px' }} key={index}>
                            {isImage
                              ? (
                                <img
                                  src={item}
                                  alt={`Preview ${index}`}
                                  width={150}
                                  height={150}
                                  style={{ objectFit: 'cover' }}
                                />
                                )
                              : (
                                <object
                                  type='application/pdf'
                                  data={item}
                                  width={150}
                                  height={150}
                                  aria-label={`Policy Doc Pdf ${index}`}
                                />
                                )}

                            {/* Close button to remove the item */}
                            <div
                              style={{
                                display: 'flex',
                                alignItems: 'start',
                                justifyContent: 'start',
                                cursor: 'pointer',
                                marginLeft: '8px'
                              }}
                              onClick={() => this.handleRemoveExtraNoteItem(item)}
                            >
                              <Icon type='close' />
                            </div>
                          </div>
                        )
                      })}
                    </div>

                    <Upload
                      name='upload'
                      showUploadList={false}
                      customRequest={(data) => this.customRequest({ ...data, uploadType: 'extra note' })}
                      listType='picture'
                      accept='.pdf, .jpg, .jpeg, .png'
                      beforeUpload={(file) => this.beforeUpload(file)}
                    >
                      {this.state.uploadingStatus
                        ? (
                          <CircularLoader isSpining />
                          )
                        : (
                          <Button>
                            <Icon type='upload' /> Click to upload
                          </Button>
                          )}
                    </Upload>
                  </>

                )}
              </Form.Item>
              <Form.Item label='Remarks'>
                {getFieldDecorator('remarks', {
                  rules: [{ required: true, message: 'Remarks field cannot be blank' }]
                })(<TextArea />)}
              </Form.Item>
              <Button type='primary' htmlType='submit'>
                Submit
              </Button>
            </Form>
          </LayoutContentStyle>
        </PolicyEndorsementStyle>
      </CircularLoader>
    )
  }
}

// Wrap component with Form.create() to inject form props
export default connect(
  (state) => ({
    agentPolicy: state.Agent.agentPolicy,
    agentCorePolicy: state.Agent.agentCorePolicy,
    getCorePolicyDetailLoader: state.Loading.GET_AGENT_INSURANCE_CORE_DATA,
    uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
    uploadPolicyFileData: state.Insurance.uploadPolicyFileData,
    dataProfile: state.Auth.profile,
    editPolicyDataMessage: state.Insurance.editPolicyDataMessage,
    submitEditPolicyData: state.Error.EDIT_POLICY_DATA
  }),
  {
    getAgentInsuranceCoreData,
    getEditPolicyAttribute,
    uploadPolicyFile,
    resetReduxState,
    editPolicyDetails
  }
)(Form.create()(PolicyCoreEndorsement))
